package com.jbrempresa.backend.core.config;
import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.stereotype.Component; import com.jbrempresa.backend.entity.ModuloAplicacion; import com.jbrempresa.backend.repository.ModuloAplicacionRepository; import java.time.LocalDateTime;
@Component public class ModulosIniciales implements ApplicationRunner{
 private final ModuloAplicacionRepository repo; public ModulosIniciales(ModuloAplicacionRepository r){repo=r;}
 private static final String[][] DATOS={{"ADMINISTRACION","Administración","Empresas, usuarios, perfiles y configuración.","administracion"},{"COMUNICACIONES","Comunicaciones","Bandeja, conversaciones y atención omnicanal.","comunicaciones"},{"TERRITORIO","Territorio","Domicilios y estructura territorial.","territorio"},{"PERSONAS","Personas","Personas, representantes y datos relacionados.","personas"},{"CLIENTES","Clientes","Gestión de clientes.","clientes"},{"EMPLEADOS","Empleados","Gestión de empleados.","empleados"},{"PROVEEDORES","Proveedores","Gestión de proveedores.","proveedores"},{"PRODUCTOS","Productos","Catálogo y gestión de productos.","productos"},{"SERVICIOS","Servicios","Catálogo, duración y gestión de servicios.","servicios"},{"COMPRAS","Compras","Compras y relación con proveedores.","compras"},{"VENTAS","Ventas","Operaciones comerciales y detalle de ventas.","ventas"},{"RECURSOS","Recursos","Empleados, maquinaria y capacidades operativas.","recursos"},{"CAJA","Caja","Aperturas, cierres y movimientos de caja.","caja"}};
 public void run(ApplicationArguments args){int p=1;for(String[] d:DATOS){if(repo.findByCodigoIgnoreCase(d[0]).isEmpty()){ModuloAplicacion m=new ModuloAplicacion();m.setCodigo(d[0]);m.setTitulo(d[1]);m.setDescripcion(d[2]);m.setRuta(d[3]);m.setPosicion(p);m.setUsuario("SISTEMA");m.setFecha(LocalDateTime.now());m.setActivo(true);repo.save(m);}p++;}}
}
